  display: inline-flex;
  margin: 8px 12px 8px 0;
  padding: 12px;
  border-radius: 18px;
  border: 3px solid transparent;
  background:
    linear-gradient(var(--dos-white), var(--dos-white)) padding-box,
    linear-gradient(135deg, var(--dos-purple), var(--dos-blue)) border-box;
  transition: transform 0.2s ease, background 0.2s ease;
